     "t": "code",
     "lang": "python",
     "code": "\"\"\"\nSingleton: only one instance of a class can exist.\nMultiple approaches: __new__, decorator, metaclass.\n\"\"\"\n\n\nclass Singleton:\n    \"\"\"Singleton using __new__ method.\"\"\"\n    _instance = None\n\n    def __new__(cls, *args, **kwargs):\n        if cls._instance is None:\n            cls._instance = super().__new__(cls)\n        return cls._instance\n\n    def __init__(self, value=None):\n        self.value = value\n\n\ndef singleton_decorator(cls):\n    \"\"\"Singleton as a decorator.\"\"\"\n    instances = {}\n\n    @functools.wraps(cls)\n    def get_instance(*args, **kwargs):\n        if cls not in instances:\n            instances[cls] = cls(*args, **kwargs)\n        return instances[cls]\n    return get_instance\n\n\n@singleton_decorator\nclass Database:\n    def __init__(self, url):\n        self.url = url\n\n\n# Examples\nprint(\"Q91: Singleton Pattern\")\ns1 = Singleton(\"first\")\ns2 = Singleton(\"second\")\nprint(s1 is s2)  # True\nprint(s1.value)  # second (last __init__ call)\n\ndb1 = Database(\"localhost:5432\")\ndb2 = Database(\"remote:5432\")\nprint(db1 is db2)  # True\nprint(db1.url)  # localhost:5432 (first call's args)\nprint()",
