     "t": "code",
     "lang": "python",
     "code": "\"\"\"\nAn immutable class prevents modification of its attributes after creation.\nApproaches: __setattr__ override, __slots__ + frozen dataclass, namedtuple.\n\"\"\"\n\n\nclass ImmutablePoint:\n    \"\"\"Immutable class using __setattr__ override.\"\"\"\n    __slots__ = ('_x', '_y')\n\n    def __init__(self, x, y):\n        object.__setattr__(self, '_x', x)\n        object.__setattr__(self, '_y', y)\n\n    @property\n    def x(self):\n        return self._x\n\n    @property\n    def y(self):\n        return self._y\n\n    def __setattr__(self, name, value):\n        raise AttributeError(\"Cannot modify immutable object\")\n\n    def __delattr__(self, name):\n        raise AttributeError(\"Cannot delete from immutable object\")\n\n    def __repr__(self):\n        return f\"ImmutablePoint(x={self._x}, y={self._y})\"\n\n\nfrom dataclasses import dataclass\n\n\n@dataclass(frozen=True)\nclass FrozenPoint:\n    \"\"\"Immutable class using frozen dataclass.\"\"\"\n    x: float\n    y: float\n\n\n# Examples\nprint(\"Q92: Immutable Class\")\np = ImmutablePoint(3, 4)\nprint(p)  # ImmutablePoint(x=3, y=4)\ntry:\n    p.x = 10\nexcept AttributeError as e:\n    print(f\"Error: {e}\")  # Cannot modify immutable object\n\nfp = FrozenPoint(1, 2)\nprint(fp)  # FrozenPoint(x=1, y=2)\ntry:\n    fp.x = 10\nexcept Exception as e:\n    print(f\"Error: {e}\")\nprint()",
