     "t": "code",
     "lang": "python",
     "code": "\"\"\"\n__slots__ restricts attribute creation to specified names only.\nBenefits:\n- Faster attribute access\n- Less memory usage (no __dict__)\n- Prevents accidental attribute creation\n\"\"\"\n\n\nclass SlotPoint:\n    \"\"\"Class using __slots__ for memory efficiency.\"\"\"\n    __slots__ = ('x', 'y', 'z')\n\n    def __init__(self, x, y, z=0):\n        self.x = x\n        self.y = y\n        self.z = z\n\n    def distance_from_origin(self):\n        return (self.x ** 2 + self.y ** 2 + self.z ** 2) ** 0.5\n\n    def __repr__(self):\n        return f\"SlotPoint({self.x}, {self.y}, {self.z})\"\n\n\n# Examples\nprint(\"Q95: Class with __slots__\")\np = SlotPoint(3, 4)\nprint(p)  # SlotPoint(3, 4, 0)\nprint(p.distance_from_origin())  # 5.0\ntry:\n    p.w = 10  # Can't add new attributes\nexcept AttributeError as e:\n    print(f\"Error: {e}\")\nprint()\n\nimport sys\n# Memory comparison\nclass RegularPoint:\n    def __init__(self, x, y):\n        self.x = x\n        self.y = y\n\nrp = RegularPoint(1, 2)\nsp = SlotPoint(1, 2)\nprint(f\"Regular __dict__ size: {sys.getsizeof(rp.__dict__)} bytes\")\n# SlotPoint has no __dict__\nprint()",
