     "t": "code",
     "lang": "python",
     "code": "\"\"\"\n__getattr__ is called ONLY when normal attribute lookup fails.\nIt's the fallback method when an attribute is not found.\nDifferent from __getattribute__ which is called for EVERY attribute access.\n\"\"\"\n\n\nclass DynamicAttributes:\n    \"\"\"Class with dynamic attribute generation.\"\"\"\n\n    def __init__(self):\n        self.data = {\"name\": \"Python\", \"version\": 3.11}\n\n    def __getattr__(self, name):\n        \"\"\"Called when attribute is not found normally.\"\"\"\n        if name in self.__dict__.get('data', {}):\n            return self.data[name]\n        raise AttributeError(f\"'{type(self).__name__}' has no attribute '{name}'\")\n\n\nclass DefaultDict:\n    \"\"\"Class that returns a default for missing attributes.\"\"\"\n\n    def __init__(self, **kwargs):\n        self.__dict__.update(kwargs)\n\n    def __getattr__(self, name):\n        return f\"<{name} not set>\"\n\n\n# Examples\nprint(\"Q96: Override __getattr__\")\nobj = DynamicAttributes()\nprint(obj.name)  # Python (from data dict)\nprint(obj.version)  # 3.11\n\nd = DefaultDict(x=10, y=20)\nprint(d.x)  # 10\nprint(d.z)  # <z not set>\nprint()",
