     "t": "code",
     "lang": "python",
     "code": "\"\"\"\n__getattribute__ is called for EVERY attribute access on an instance.\nBe careful of infinite recursion - use object.__getattribute__ for internal access.\nThis is a powerful but dangerous method to override.\n\"\"\"\n\n\nclass LoggedAccess:\n    \"\"\"Class that logs every attribute access.\"\"\"\n\n    def __init__(self, **kwargs):\n        for k, v in kwargs.items():\n            object.__setattr__(self, k, v)\n\n    def __getattribute__(self, name):\n        \"\"\"Called for every attribute access.\"\"\"\n        if not name.startswith('_'):\n            print(f\"Accessing attribute: {name}\")\n        # MUST use object.__getattribute__ to avoid infinite recursion\n        return object.__getattribute__(self, name)\n\n\nclass ReadOnly:\n    \"\"\"Class where all attributes become read-only after init.\"\"\"\n\n    def __init__(self, **kwargs):\n        object.__setattr__(self, '_initialized', False)\n        for k, v in kwargs.items():\n            object.__setattr__(self, k, v)\n        object.__setattr__(self, '_initialized', True)\n\n    def __setattr__(self, name, value):\n        if object.__getattribute__(self, '_initialized'):\n            raise AttributeError(\"Cannot modify read-only object\")\n        object.__setattr__(self, name, value)\n\n\n# Examples\nprint(\"Q97: Override __getattribute__\")\nobj = LoggedAccess(name=\"Python\", version=3)\n_ = obj.name  # Logs: Accessing attribute: name\n_ = obj.version  # Logs: Accessing attribute: version\nprint()",
