     "t": "code",
     "lang": "python",
     "code": "\"\"\"\nA simplified ORM that maps Python classes to database-like records.\nSupports field definition, validation, and basic CRUD operations in memory.\n\"\"\"\n\n\nclass Field:\n    \"\"\"Base field descriptor for ORM.\"\"\"\n\n    def __init__(self, field_type, required=True, default=None):\n        self.field_type = field_type\n        self.required = required\n        self.default = default\n\n    def __set_name__(self, owner, name):\n        self.name = name\n        self.private_name = f\"_{name}\"\n\n    def __get__(self, obj, objtype=None):\n        if obj is None:\n            return self\n        return getattr(obj, self.private_name, self.default)\n\n    def __set__(self, obj, value):\n        if value is None and self.required:\n            raise ValueError(f\"{self.name} is required\")\n        if value is not None and not isinstance(value, self.field_type):\n            raise TypeError(\n                f\"{self.name} must be {self.field_type.__name__}\"\n            )\n        setattr(obj, self.private_name, value)\n\n\nclass StringField(Field):\n    def __init__(self, max_length=None, **kwargs):\n        super().__init__(str, **kwargs)\n        self.max_length = max_length\n\n    def __set__(self, obj, value):\n        super().__set__(obj, value)\n        if value and self.max_length and len(value) > self.max_length:\n            raise ValueError(\n                f\"{self.name} exceeds max length of {self.max_length}\"\n            )\n\n\nclass IntField(Field):\n    def __init__(self, min_value=None, max_value=None, **kwargs):\n        super().__init__(int, **kwargs)\n        self.min_value = min_value\n        self.max_value = max_value\n\n    def __set__(self, obj, value):\n        super().__set__(obj, value)\n        if value is not None:\n            if self.min_value is not None and value < self.min_value:\n                raise ValueError(f\"{self.name} must be >= {self.min_value}\")\n            if self.max_value is not None and value > self.max_value:\n                raise ValueError(f\"{self.name} must be <= {self.max_value}\")\n\n\nclass ModelMeta(type):\n    \"\"\"Metaclass that collects field definitions.\"\"\"\n\n    def __new__(mcs, name, bases, namespace):\n        fields = {}\n        for key, value in namespace.items():\n            if isinstance(value, Field):\n                fields[key] = value\n        namespace['_fields'] = fields\n        namespace['_storage'] = []  # In-memory storage\n        namespace['_id_counter'] = 0\n        return super().__new__(mcs, name, bases, namespace)\n\n\nclass Model(metaclass=ModelMeta):\n    \"\"\"Base model class with CRUD operations.\"\"\"\n\n    def __init__(self, **kwargs):\n        for field_name, field in self._fields.items():\n            value = kwargs.get(field_name, field.default)\n            setattr(self, field_name, value)\n        self.__class__._id_counter += 1\n        self.id = self.__class__._id_counter\n\n    def save(self):\n        \"\"\"Save instance to storage.\"\"\"\n        # Check if already exists (update)\n        for i, record in enumerate(self._storage):\n            if record.id == self.id:\n                self._storage[i] = self\n                return self\n        self._storage.append(self)\n        return self\n\n    @classmethod\n    def all(cls):\n        \"\"\"Return all records.\"\"\"\n        return cls._storage[:]\n\n    @classmethod\n    def find(cls, **kwargs):\n        \"\"\"Find records matching criteria.\"\"\"\n        results = []\n        for record in cls._storage:\n            match = all(\n                getattr(record, k, None) == v for k, v in kwargs.items()\n            )\n            if match:\n                results.append(record)\n        return results\n\n    @classmethod\n    def get(cls, id):\n        \"\"\"Get a record by ID.\"\"\"\n        for record in cls._storage:\n            if record.id == id:\n                return record\n        return None\n\n    def delete(self):\n        \"\"\"Delete this record.\"\"\"\n        self._storage[:] = [r for r in self._storage if r.id != self.id]\n\n    def to_dict(self):\n        \"\"\"Convert to dictionary.\"\"\"\n        data = {\"id\": self.id}\n        for field_name in self._fields:\n            data[field_name] = getattr(self, field_name)\n        return data\n\n    def __repr__(self):\n        fields = \", \".join(f\"{k}={getattr(self, k)!r}\" for k in self._fields)\n        return f\"{self.__class__.__name__}(id={self.id}, {fields})\"\n\n\n# Define a User model\nclass User(Model):\n    name = StringField(max_length=50)\n    email = StringField(max_length=100)\n    age = IntField(min_value=0, max_value=150)\n\n\n# Examples\nprint(\"Q100: Simple ORM-like Model\")\nuser1 = User(name=\"Alice\", email=\"alice@example.com\", age=30)\nuser1.save()\nuser2 = User(name=\"Bob\", email=\"bob@example.com\", age=25)\nuser2.save()\nuser3 = User(name=\"Alice\", email=\"alice2@example.com\", age=28)\nuser3.save()\n\nprint(f\"All users: {User.all()}\")\nprint(f\"Find Alice: {User.find(name='Alice')}\")\nprint(f\"Get by ID 2: {User.get(2)}\")\nprint(f\"User 1 dict: {user1.to_dict()}\")\n\ntry:\n    bad_user = User(name=\"X\" * 100, email=\"test@test.com\", age=30)\nexcept ValueError as e:\n    print(f\"Validation error: {e}\")\nprint()\n\n\n# STRING ALGORITHMS - EXTENDED (Q651 - Q652, bonus)",
